import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

function App() {
    var value = React.useState({ d: '0', h: '2', m: '30' }), interval = React.useState({ h: '0', m: '15' }), error = React.useState(''), applied = React.useState('');
    function apply() {
        var minutes = Number(interval[0].h || 0) * 60 + Number(interval[0].m || 0);
        if (Number(interval[0].m || 0) > 59) {
            error[1]('Укажите минуты от 0 до 59.');
            applied[1]('');
            return;
        }
        if (!minutes) {
            error[1]('Интервал должен быть больше нуля.');
            applied[1]('');
            return;
        }
        error[1]('');
        applied[1]('Применён интервал: ' + minutes + ' мин.');
    }
    return <div className="dsduration-example">
    <style>{exampleStyles}</style>
    <div className={"demo-stack"}>
    <div role={'group'} aria-label={'Интервал отчёта'}>
    <S.DsDuration label={'Интервал отчёта'} showDays={false} value={interval[0]} onChange={function (v) { interval[1](v); error[1](''); applied[1](''); }} hint={'Укажите положительный интервал; минуты от 0 до 59.'} error={error[0]}/>
    </div>
    <div className={'row'}>
    <S.DsButton onClick={apply}>
    {'Применить'}
    </S.DsButton>
    <S.DsButton tone={'secondary'} onClick={function () { interval[1]({ h: '0', m: '15' }); error[1](''); applied[1](''); }}>
    {'Сбросить'}
    </S.DsButton>
    </div>
    <p className={'cap'} role={'status'}>
    {error[0] || applied[0]}
    </p>
    <p className={'cap'}>
    {'В этом примере проверка интервала выполняется при нажатии «Применить».'}
    </p>
    </div>
    </div>;
}

const exampleStyles = ".dsduration-example{font:var(--ds-type-body);color:var(--ds-fg)}\n.dsduration-example .demo-stack{display:flex;flex-direction:column;gap:16px;min-width:0}\n.dsduration-example p{margin:0}\n.dsduration-example .row{display:flex;flex-wrap:wrap;gap:8px;align-items:center}.dsduration-example .cap{font:var(--ds-type-caption);color:var(--ds-fg-muted)}";

export { App as Example };
